<section class="help-page-head"><div class="help-shell"><?php $this->insert('components/breadcrumb', ['items' => [['label' => $category['product_name'], 'url' => '/help/products/' . rawurlencode((string) $category['product_slug'])], ['label' => $category['name']]]]); ?><p class="help-eyebrow">CATEGORIA · <?= $this->e((string) $category['product_name']) ?></p><h1><?= $this->e((string) $category['name']) ?></h1><p><?= $this->e((string) ($category['description'] ?: 'Artigos e instruções desta categoria.')) ?></p></div></section>
